<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';
require_once __DIR__ . '/../includes/ordens_limpeza.php';
ol_require_access();ol_require_schema($pdo);
$id=(int)($_GET['id']??0);$order=ol_get($pdo,$id);if(!$order)throw new RuntimeException('Ordem de Limpeza não encontrada.');
$participants=ol_participants($pdo,$id);$items=ol_items($pdo,$id);$photos=ol_photos($pdo,$id);
?>
<!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($order['numero_ol'])?></title><style>body{font-family:Arial,sans-serif;color:#111;margin:28px;font-size:13px}.head{display:flex;justify-content:space-between;border-bottom:3px solid #0b2341;padding-bottom:12px}.brand{font-size:20px;font-weight:bold;color:#0b2341}.meta{text-align:right}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.box{border:1px solid #bbb;border-radius:6px;padding:9px}.label{font-size:10px;text-transform:uppercase;color:#666}.section{margin-top:18px}.section h2{font-size:15px;border-bottom:1px solid #bbb;padding-bottom:5px}.check{font-size:17px;margin-right:6px}.row{display:flex;gap:12px}.photo{width:150px;height:110px;object-fit:cover;border:1px solid #aaa}.no-print{margin-bottom:18px}@media print{.no-print{display:none}body{margin:12mm}}</style></head><body>
<button class="no-print" onclick="window.print()">Imprimir</button>
<div class="head"><div><div class="brand">GEOP · Shopping Carpina</div><div>Ordem de Limpeza</div></div><div class="meta"><strong style="font-size:18px"><?=e($order['numero_ol'])?></strong><br><?=e(date('d/m/Y H:i',strtotime($order['criado_em'])))?></div></div>
<div class="grid"><div class="box"><div class="label">Status</div><?=e(ol_status_label($order['status']))?></div><div class="box"><div class="label">Prioridade</div><?=e(ol_priorities()[$order['prioridade']]??$order['prioridade'])?></div><div class="box"><div class="label">Tipo</div><?=e(ol_types()[$order['tipo']]??$order['tipo'])?></div><div class="box"><div class="label">Ambiente/local</div><?=e($order['ambiente_nome']?:$order['local_nome']?:'-')?></div><div class="box"><div class="label">Data programada</div><?=e($order['data_programada']?date('d/m/Y',strtotime($order['data_programada'])):'-')?> <?=e($order['hora_inicio_prevista']?substr($order['hora_inicio_prevista'],0,5):'')?></div><div class="box"><div class="label">Supervisor</div><?=e($order['supervisor_membro_nome']?:'-')?></div></div>
<div class="section"><h2><?=e($order['titulo'])?></h2><p><?=nl2br(e($order['descricao']?:'Sem descrição adicional.'))?></p></div>
<div class="section"><h2>Equipe</h2><?php foreach($participants as $participant): ?><div>• <?=e($participant['nome_colaborador'])?> — <?=e($participant['cargo'])?><?=((int)$participant['responsavel_principal']===1?' (principal)':'')?><?=((int)$participant['executou']===1?' — executou':'')?></div><?php endforeach ?></div>
<div class="section"><h2>Checklist</h2><?php foreach($items as $item): ?><div style="margin:7px 0"><span class="check"><?=$item['status_item']==='CONCLUIDO'?'☑':'☐'?></span><?=e($item['descricao'])?> — <?=e(str_replace('_',' ',$item['status_item']))?><?php if($item['observacao_execucao']): ?> (<?=e($item['observacao_execucao'])?>)<?php endif ?></div><?php endforeach ?></div>
<?php foreach(['observacao_execucao'=>'Observação da execução','problema_encontrado'=>'Problema encontrado','insumos_utilizados'=>'Insumos utilizados','parecer_validacao'=>'Parecer da validação'] as $field=>$label): if(trim((string)$order[$field])!==''): ?><div class="section"><h2><?=e($label)?></h2><p><?=nl2br(e($order[$field]))?></p></div><?php endif;endforeach ?>
<?php if($photos): ?><div class="section"><h2>Evidências</h2><div class="row"><?php foreach(array_slice($photos,0,4) as $photo): ?><img class="photo" src="<?=e(app_path($photo['arquivo_url']))?>" alt="Evidência"><?php endforeach ?></div></div><?php endif ?>
<div class="section" style="margin-top:35px"><div class="row"><div style="flex:1;border-top:1px solid #333;text-align:center;padding-top:5px">Responsável pela execução</div><div style="flex:1;border-top:1px solid #333;text-align:center;padding-top:5px">Supervisor/Validador</div></div></div>
</body></html>
